import {readFileSync,writeFileSync} from "node:fs";
import {gunzipSync} from "node:zlib";
import assert from "node:assert/strict";
import {computeIdlePriorityFeatures,evaluateIdleGenericCandidate,evaluateIdlePriorityShort,type IdleH1Candle} from "../lib/idle-priority-short-signal";
import {reviewIdleResearchBatch,initialIdleResearch,type IdleTapeRow} from "../lib/stable4-idle-research-policy";
import {advanceFetBrk48LongTrailingStop,type FetBrk48TrailingStopState} from "../lib/fet-brk48-trailing-stop";
import {FET_BRK48_RESIDUAL as policy} from "../config/fetBrk48Runtime";
import type {IdlePrioritySymbol} from "../config/idlePriorityShortPolicy";
const B=String.raw`C:\tmp\disdex-bt-20251001-20261001`,R=String.raw`C:\tmp\disdex-d126-crossrunner-research-20261126`,H=3600000,M=300000;
const begin=Date.parse("2025-10-01T00:00:00Z"),end=Date.parse("2026-10-01T00:00:00Z");
const gzip=(p:string)=>gunzipSync(readFileSync(p)).toString("utf8").trim().split(/\r?\n/).map(x=>JSON.parse(x));
const load=(s:string):Map<number,IdleH1Candle>=>new Map(gzip(B+"/aster-public-v3-h1/"+s+"-1h-20250924-20261001.jsonl.gz").map(r=>[Number(r[0]),{ts:Number(r[0]),open:Number(r[1]),high:Number(r[2]),low:Number(r[3]),close:Number(r[4]),quoteVolume:Number(r[7])}]));
const btc=load("BTCUSDT"),symbols=["TAOUSDT","TIAUSDT","DOTUSDT","JUPUSDT","RENDERUSDT"] as const;
const data=new Map(symbols.map(s=>[s,load(s)]));
const window=(m:Map<number,IdleH1Candle>,t:number)=>Array.from({length:73},(_,i)=>m.get(t-(73-i)*H)).filter((r):r is IdleH1Candle=>!!r);
const errors:Record<string,number>={},actual:IdleTapeRow[]=[],accepted:IdleTapeRow[]=[];let state=initialIdleResearch();
for(let t=begin;t<end;t+=H){
 const b=window(btc,t),rows:IdleTapeRow[]=[];
 for(const sym of symbols){
  try{
   const f=computeIdlePriorityFeatures(t,window(data.get(sym)!,t),b);
   const x=evaluateIdlePriorityShort(sym,f,evaluateIdleGenericCandidate(f));
   if(x.accepted)rows.push({entryTs:t,symbol:sym,route:x.route,features:f});
  }catch(e){const m=(e as Error).message;errors[m]=(errors[m]??0)+1;}
 }
 actual.push(...rows);const x=reviewIdleResearchBatch(state,t,rows);state=x.state;accepted.push(...x.decisions.filter(d=>d.retained).map(d=>d.row));
}
const raw=readFileSync(B+"/DIRECTION_RESEARCH_20261109/IDLE_CURRENT_PRODUCTION_REPLAY_20261110/idle-route-candidates-no-cooldown.jsonl","utf8").trim().split(/\r?\n/).map(x=>JSON.parse(x));
const key=(x:IdleTapeRow)=>[x.entryTs,x.symbol,x.route].join("|"),expected=new Map<string,any>(raw.map(x=>[key(x),x])),got=new Map(actual.map(x=>[key(x),x]));
const missing=[...expected.keys()].filter(k=>!got.has(k)),extra=[...got.keys()].filter(k=>!expected.has(k));const featureMismatch:string[]=[];
for(const [k,x]of got){const y=expected.get(k);if(y&&Object.entries(x.features).some(([f,v])=>typeof v==="number"?Math.abs(v-y.features[f])>1e-12:v!==y.features[f]))featureMismatch.push(k);}
const fet=JSON.parse(readFileSync(B+"/native-new-signal-20251001-20261001/native-FET-all-intent-modeled-5m-exit-audit.json","utf8")).trades;
const fbars=new Map<number,any[]>([...gzip(B+"/aster-public-v3-5m-prefix/FETUSDT-5m-20250924-20260803.jsonl.gz"),...gzip(B+"/aster-public-v3-5m-suffix/FETUSDT-5m-20260803-20261001.jsonl.gz")].map(r=>[Number(r[0]),r]));
const results:any[]=[];
for(const x of fet){
 const t=x.entryTs,entry=Number(fbars.get(t)?.[1]),until=t+policy.holdHours*H;
 let stop=entry*(1-policy.hardStopPct),trail:FetBrk48TrailingStopState|undefined,exit:any;
 for(let j=t;j<until;j+=M){
  const r=fbars.get(j);if(!r){exit={reason:"GAP",ts:j};break;}
  const [o,h,l,c]=r.slice(1,5).map(Number);
  if(l<=stop+1e-12){exit={reason:"FET_PROTECTED_STOP",ts:j,price:Math.min(o,stop)};break;}
  const res=advanceFetBrk48LongTrailingStop({entryPrice:entry,state:trail,bar:{timestampMs:j,open:o,high:h,low:l,close:c}});
  trail=res.state;
  if(c>=entry*(1+policy.profitFloorTriggerPct)-1e-12)stop=Math.max(stop,entry*(1+policy.profitFloorStopPct));
  if(trail.stopPrice!==undefined)stop=Math.max(stop,trail.stopPrice);
 }
 if(!exit)exit={reason:"MAX_HOLD",ts:until,price:Number(fbars.get(until)?.[1])};
 const ok=entry===x.entryPrice&&exit.ts===x.exitTs&&exit.reason===x.exitReason&&Math.abs(exit.price-x.exitPrice)<1e-10;
 results.push({entryTs:t,entry,expected:{ts:x.exitTs,reason:x.exitReason,price:x.exitPrice},actual:exit,ok});
}
const out={idle:{expected:raw.length,actual:actual.length,retained:accepted.length,missing,extra,featureMismatch,errors},fet:{total:results.length,matched:results.filter(r=>r.ok).length,results}};
writeFileSync(R+"/STABLE4_IDLE_FET_RAW_REGEN_AUDIT_20261127.json",JSON.stringify(out,null,2));console.log(JSON.stringify(out));if(missing.length||extra.length||featureMismatch.length||accepted.length!==197||results.some(x=>!x.ok))process.exitCode=1;
